set -eu
sudo docker exec quickreels-api-1 node -e 'const {loadEnv}=require("./dist/config/env");const {configuredMiniAppKeys,miniAppEnvironment}=require("./dist/config/mini-apps");const e=loadEnv();const apps=configuredMiniAppKeys(e);console.log(JSON.stringify({configuredApps:apps.length,mainPool:new URL(e.DATABASE_URL).searchParams.get("connection_limit"),sharedSeparate:Boolean(e.SHARED_PLATFORM_DATABASE_URL&&e.SHARED_PLATFORM_DATABASE_URL!==e.DATABASE_URL),sample:Object.fromEntries(["talereels","sweetreel","crownreel","heartreel","dramablaze"].map(k=>[k,new URL(miniAppEnvironment(e,k).DATABASE_URL).searchParams.get("connection_limit")]))}))'
sudo docker exec quickreels-postgres-1 sh -c 'psql -U "$POSTGRES_USER" -d postgres -Atc "show max_connections; select count(*) from pg_stat_activity"'
